ALTER TABLE "materials" DROP CONSTRAINT "materials_family";--> statement-breakpoint
ALTER TABLE "tasting_families" DROP CONSTRAINT "tasting_families_code";--> statement-breakpoint
ALTER TABLE "materials" ADD CONSTRAINT "materials_family" CHECK ("materials"."family" is null or "materials"."family" in ('citrus', 'green', 'ozonic', 'floral', 'fruity', 'spicy', 'woody', 'animal', 'transformed', 'gourmand'));--> statement-breakpoint
ALTER TABLE "tasting_families" ADD CONSTRAINT "tasting_families_code" CHECK (case "tasting_families"."scheme" when 'calkin' then code in ('aldehydic', 'amber', 'animal', 'anisic', 'aromatic_herbal', 'balsamic', 'camphoraceous', 'cinnamic', 'citrus', 'floral', 'fresh', 'fruity', 'green', 'herbal', 'iris', 'lavender', 'leather', 'linalool', 'minty', 'mossy', 'musky', 'spicy', 'sweet', 'melon_cucumber') when 'ellena' then code in ('flowers', 'fruits', 'woods', 'herbs', 'spices', 'sweets', 'animals', 'marine', 'minerals') when 'app' then code in ('citrus', 'green', 'ozonic', 'floral', 'fruity', 'spicy', 'woody', 'animal', 'transformed', 'gourmand') else false end);